#!/usr/bin/env bash
# Evaluate ONE KIMODO-SMPLX control task (keyframe / traj / spatial) generated by
# gen_kimodo_m2m_smplx.py:
#   (1) distribution metrics: motion_135 (row-major) -> MotionStreamer-272 vs
#       NATIVE GT-272 (FID / R@k / MM-Dist / Diversity), same path as the temporal
#       eval (SMPL-X output encoded DIRECTLY to 272, no 263->IK lift).
#   (2) control metrics: eval_kimodo_m2m_smplx_control.py
#         keyframe -> KPS Err / MPJPE(world) / Fail@20/50 / foot / jitter
#         traj     -> Traj.Err / Fail@20/50 / foot / jitter
#         spatial  -> Ctrl.Err (geodesic deg on kept joints) / foot / jitter
#
# Usage: bash scripts/eval/eval_kimodo_m2m_smplx_control.sh <TASK> <KIND> [BASE_DIR] [GPU]
#   TASK e.g. keyframe / traj_xz_dense / spatial_upper
#   KIND in {keyframe, traj, spatial}
set -uo pipefail
cd /apdcephfs_cq11/share_1467498/home/zeyuling/hf_trainer 2>/dev/null \
  || cd /apdcephfs/AILab_DHA/apdcephfs_cq11/share_1467498/home/zeyuling/hf_trainer
ROOT="$PWD"
export PYTHONPATH="$ROOT:${PYTHONPATH:-}" PYTHONUNBUFFERED=1 TOKENIZERS_PARALLELISM=false

TASK="${1:?usage: eval_kimodo_m2m_smplx_control.sh <TASK> <KIND> [BASE_DIR] [GPU]}"
KIND="${2:?need KIND keyframe/traj/spatial}"
BASE="${3:-outputs/evaluation/kimodo_smplx_m2m_20260623/${TASK}}"
GPU="${4:-0}"
PRED="$BASE/preds_npz"
MET="$BASE/metrics"; mkdir -p "$MET"
LOG="$BASE/evallogs"; mkdir -p "$LOG"

echo "[eval] task=$TASK kind=$KIND pred=$PRED npz=$(ls "$PRED"/*.npz 2>/dev/null | wc -l)"

bash scripts/eval/_cache_272_data.sh > "$LOG/cache.log" 2>&1 || true

echo "[eval] distribution (MotionStreamer-272) ..."
CUDA_VISIBLE_DEVICES="$GPU" python3 scripts/eval/eval_motionstreamer_272.py \
  --pred-dir "$PRED" --tag "kimodo_smplx_${TASK}" --also-refk \
  --out-json "$MET/ms272.json" > "$LOG/ms272.log" 2>&1
echo "[eval] dist -> $MET/ms272.json"

echo "[eval] control ($KIND) ..."
CUDA_VISIBLE_DEVICES="$GPU" python3 scripts/eval/eval_kimodo_m2m_smplx_control.py \
  --pred-dir "$PRED" --kind "$KIND" --out "$MET/control.json" > "$LOG/control.log" 2>&1
tail -n 12 "$LOG/control.log"
echo "[eval] control -> $MET/control.json"

python3 - "$MET/ms272.json" "$MET/control.json" "$TASK" "$KIND" <<'PY'
import json, sys
ms, ctrl, task, kind = sys.argv[1:5]
d = json.load(open(ms)); c = json.load(open(ctrl)); pr = d.get("pred", {})
rp = pr.get("r_precision", [float("nan")]*3)
print(f"\n=== KIMODO-SMPLX {task} ({kind}) SUMMARY ===")
print(f" dist n={d.get('ids_with_required_files')}  "
      f"FID={pr.get('fid_vs_gt_native',float('nan')):.1f}  "
      f"R@1/2/3={rp[0]:.3f}/{rp[1]:.3f}/{rp[2]:.3f}  "
      f"MM={pr.get('matching_score',float('nan')):.2f}  "
      f"Div={pr.get('diversity',float('nan')):.2f}")
if kind == "keyframe":
    print(f" ctrl n={c['n_samples']}  KPS={c['kps_err_mean']*100:.1f}cm  "
          f"MPJPE={c['mpjpe_world_mean']*100:.1f}cm  "
          f"Fail@20={c['fail20_mean']:.2f}  Fail@50={c['fail50_mean']:.2f}  "
          f"foot={c['foot_skating_mean']:.3f}  jitter={c['jitter_mean']:.1f}")
elif kind == "traj":
    print(f" ctrl n={c['n_samples']}  TrajErr={c['traj_err_mean']:.3f}m  "
          f"Fail@20={c['fail20_mean']:.3f}  Fail@50={c['fail50_mean']:.3f}  "
          f"foot={c['foot_skating_mean']:.3f}  jitter={c['jitter_mean']:.1f}")
else:
    print(f" ctrl n={c['n_samples']}  Ctrl.Err={c['ctrl_err_deg_mean']:.2f}deg  "
          f"foot={c['foot_skating_mean']:.3f}  jitter={c['jitter_mean']:.1f}")
PY
echo "EVAL_DONE task=$TASK"
